import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Docker Compose","description":"Copy the deploy/ folder, edit one .env, and start the official image plus PostgreSQL and Redis.","frontmatter":{"title":"Docker Compose","description":"Copy the deploy/ folder, edit one .env, and start the official image plus PostgreSQL and Redis."},"headers":[],"relativePath":"en/guide/install/compose.md","filePath":"en/guide/install/compose.md","lastUpdated":1790057721000}`),a={name:`en/guide/install/compose.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="docker-compose" tabindex="-1">Docker Compose <a class="header-anchor" href="#docker-compose" aria-label="Permalink to “Docker Compose”">​</a></h1><p><a href="https://github.com/Kirizu-Official/KiriVers/tree/main/deploy" target="_blank" rel="noreferrer"><code>deploy/</code></a> is the operator one-click pack: official image + PostgreSQL + Redis. Copy the whole folder to a server; you do not need other files from the repo.</p><div class="info custom-block"><p class="custom-block-title">Not the developer file</p><p><code>dev/docker/compose.yml</code> starts Postgres/Redis for local <code>go run .</code> only. It does <strong>not</strong> run KiriVers. <code>deploy/</code> is the only operator one-click Compose pack in the repo (<code>dev/build/</code> holds no Compose file any more — just the runtime <code>Dockerfile</code> and the release CLI).</p></div><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to “Start”">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># set POSTGRES_PASSWORD, REDIS_PASSWORD, URL_SIGNING_SECRET</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>.env</code> is the only password file. The same values feed:</p><table tabindex="0"><thead><tr><th>In <code>.env</code></th><th>Applied to</th></tr></thead><tbody><tr><td><code>POSTGRES_*</code></td><td>the PostgreSQL container and <code>KIRIVERS_POSTGRES_DSN</code></td></tr><tr><td><code>REDIS_PASSWORD</code></td><td>Redis <code>requirepass</code> and <code>KIRIVERS_CACHE_REDIS_PASSWORD</code></td></tr><tr><td><code>URL_SIGNING_SECRET</code></td><td><code>KIRIVERS_URL_SIGNING_SECRET</code></td></tr></tbody></table><p><code>deploy/config/</code> already has the three YAML files. <strong>Do not</strong> copy <code>configs/*-example.yaml</code> again. <code>CHANGE_ME</code> in YAML is overridden by <code>.env</code>; editing database passwords in YAML has no effect.</p><p>The process uses <code>KIRIVERS_CACHE_DRIVER=redis</code> at <code>redis:6379</code>. Expect <code>postgres</code>, <code>redis</code>, and <code>kirivers</code> in <code>docker compose ps</code>. Open <code>http://127.0.0.1:8081</code>.</p><p>Data lives in <code>deploy/data/</code> (Postgres, Redis AOF, packages, logs). Only <code>8080</code> and <code>8081</code> are published.</p><div class="danger custom-block"><p class="custom-block-title">Sample passwords</p><p><code>CHANGE_ME</code> in <code>.env.example</code> is not a production secret.</p></div><h2 id="which-image-tag" tabindex="-1">Which image tag <a class="header-anchor" href="#which-image-tag" aria-label="Permalink to “Which image tag”">​</a></h2><p><code>deploy/compose.yml</code> pins <code>kirizuofficial/kirivers:latest</code>, i.e. the <strong>most recent release</strong>. To stay on a specific version, change the <code>image:</code> line:</p><table tabindex="0"><thead><tr><th>Tag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>kirizuofficial/kirivers:latest</code></td><td>the latest release</td></tr><tr><td><code>kirizuofficial/kirivers:&lt;semver&gt;</code></td><td>that version&#39;s multi-arch manifest (the host architecture picks its own image)</td></tr><tr><td><code>kirizuofficial/kirivers:&lt;semver&gt;_amd64</code> / <code>&lt;semver&gt;_arm64</code></td><td>that version&#39;s single-architecture image; use only when you deliberately lock an architecture</td></tr></tbody></table><p>Official images exist for <code>linux/amd64</code> and <code>linux/arm64</code> only (Alpine base, musl build). Other Linux architectures have no image — use a <a href="/en/guide/install/manual">Releases zip archive</a> instead. Before upgrading, back up PostgreSQL and <code>storage.local.root</code>, then <code>docker compose pull &amp;&amp; docker compose up -d</code>.</p><p>Next: <a href="/en/guide/config/bootstrap-admin">bootstrap admin</a>.</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};